// Bộ biểu tượng của app, vẽ bằng SVG theo kiểu khối 3D mềm: không viền, màu chuyển sắc, có điểm sáng.
// Dữ liệu vẫn lưu biểu tượng bằng emoji như cũ (chores.icon, rewards.icon...); lúc hiện ra, emoji nào có hình
// trong bộ này thì được thay bằng hình vẽ, emoji khác giữ nguyên.
//   - iconSvg('ten')  : SVG theo tên.
//   - icon('🛏️')      : SVG theo emoji, không có thì trả lại emoji.
//   - autoIcons()     : tự thay emoji trong cả trang (kể cả phần được vẽ lại sau này).

// Bảng màu: [sáng, đậm]. Mỗi màu có 2 kiểu tô: "@y" chuyển sắc chéo (khối phẳng), "@Y" chuyển sắc tròn (khối cầu).
const PAL = {
  y: ['#FFE066', '#F7A81B'], o: ['#FFB65C', '#F0741A'], r: ['#FF8088', '#E0304C'], p: ['#FFB9CE', '#F0669A'],
  v: ['#C2A8FF', '#7A52E6'], b: ['#7FD6FF', '#1C92E8'], t: ['#80E8D8', '#16AE9E'], g: ['#98E88C', '#27B25A'],
  n: ['#DDAE84', '#A56B3B'], d: ['#FBDA9E', '#E3A04E'], c: ['#FFEDD2', '#F1C08A'], k: ['#666C80', '#272B37'],
  w: ['#FFFFFF', '#D9E2EE'], s: ['#F2F5F9', '#96A1B3'],
};
const DEFS = Object.entries(PAL).map(([k, [a, b]]) =>
  `<linearGradient id="ig-${k}" x1=".15" y1="0" x2=".85" y2="1"><stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`
  + `<radialGradient id="ig-${k.toUpperCase()}" cx=".34" cy=".28" r=".82"><stop offset="0" stop-color="${a}"/><stop offset=".55" stop-color="${b}"/><stop offset="1" stop-color="${b}"/></radialGradient>`).join('')
  + '<radialGradient id="ig-edge" cx=".42" cy=".36" r=".66"><stop offset=".72" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".2"/></radialGradient>';

const H = 'fill="#fff" opacity=".45"';   // điểm sáng
const INK = '#3A2A20';                   // mắt, mũi, nét mặt
const rnd = n => Math.round(n * 100) / 100;
// Khối cầu: màu chuyển sắc tròn, viền dưới sẫm lại, một vệt sáng phía trên.
const ball = (cx, cy, r, c) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="@${c.toUpperCase()}"/><circle cx="${cx}" cy="${cy}" r="${r}" fill="@edge"/>`
  + `<ellipse cx="${rnd(cx - r * .38)}" cy="${rnd(cy - r * .55)}" rx="${rnd(r * .36)}" ry="${rnd(r * .2)}" transform="rotate(-32 ${rnd(cx - r * .38)} ${rnd(cy - r * .55)})" ${H}/>`;
const eyes = (x1, x2, y, r = 2.2) => `<ellipse cx="${x1}" cy="${y}" rx="${r}" ry="${rnd(r * 1.25)}" fill="${INK}"/><ellipse cx="${x2}" cy="${y}" rx="${r}" ry="${rnd(r * 1.25)}" fill="${INK}"/>`;
// Ngôi sao 4 cánh (lấp lánh).
const spark = (x, y, R, fill = '@y') => { const q = rnd(R * .2); return `<path d="M${x} ${y - R}Q${x + q} ${y - q} ${x + R} ${y}Q${x + q} ${y + q} ${x} ${y + R}Q${x - q} ${y + q} ${x - R} ${y}Q${x - q} ${y - q} ${x} ${y - R}z" fill="${fill}"/>`; };
