const star = (x, y, s, fill = '@y') => `<path d="${STAR5}" transform="translate(${rnd(x - 12 * s)} ${rnd(y - 12 * s)}) scale(${s})" fill="${fill}" stroke="${fill}" stroke-width="2" stroke-linejoin="round"/>`;
// Người: đầu tròn, tóc, thân áo.
const person = (x, y, r, shirt, hair = '#7A4A26') => `<path d="M${rnd(x - r * 1.75)} ${rnd(y + r * 4.2)}v-${rnd(r * .9)}a${rnd(r * 1.75)} ${rnd(r * 1.75)} 0 0 1 ${rnd(r * 3.5)} 0v${rnd(r * .9)}z" fill="${shirt}"/>`
  + `<circle cx="${x}" cy="${y}" r="${r}" fill="@C"/><path d="M${x - r} ${rnd(y + r * .1)}a${r} ${r} 0 0 1 ${2 * r} 0c-${rnd(r * .6)}-${rnd(r * .75)}-${rnd(r * 1.4)}-${rnd(r * .75)}-${2 * r} 0z" fill="${hair}"/>`;
